INSERT INTO Vacancy (name, description, CATEGORY_ID, salary, EXP_FROM, EXP_TO, IS_ACTIVE, AUTHOR_ID, CREATED_DATE, UPDATE_TIME)
VALUES ('Junior Developer','Seeking a junior developer with some experience in coding. Ideal for those eager to learn and grow in a supportive team environment. Experience with front-end or back-end technologies is a plus.',(SELECT id FROM Category WHERE name = 'Development' LIMIT 1),1200.0,3,5,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-03-01','2023-07-01'),
       ('Senior Developer','Looking for a senior developer with extensive experience in software development. Responsibilities include leading projects, mentoring junior developers, and ensuring high-quality code. Experience with various programming languages required.',(SELECT id FROM Category WHERE name = 'Development' LIMIT 1),2000.0,5,10,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-04-01','2023-07-10'),
       ('UX Designer','A creative UX Designer needed to enhance user experiences. Responsibilities include researching user needs, designing wireframes, and collaborating with developers. Previous experience with design tools is a must.',(SELECT id FROM Category WHERE name = 'Design' LIMIT 1),1500.0,2,5,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-05-01','2023-08-01'),
       ('Project Manager','Experienced Project Manager required to oversee project development from initiation to completion. Must have experience managing cross-functional teams and ensuring project milestones are met.',(SELECT id FROM Category WHERE name = 'IT' LIMIT 1),2500.0,5,12,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-06-01','2023-08-15'),
       ('Frontend Developer','Frontend Developer with experience in modern JavaScript frameworks needed. Responsibilities include developing user interfaces, collaborating with backend developers, and optimizing performance.',(SELECT id FROM Category WHERE name = 'Development' LIMIT 1),1400.0,3,7,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-07-01','2023-08-20'),
       ('Backend Developer','Looking for a Backend Developer with strong experience in server-side technologies. Responsibilities include building and maintaining server applications, working with databases, and ensuring scalability.',(SELECT id FROM Category WHERE name = 'Development' LIMIT 1),1600.0,4,8,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-08-01','2023-09-01'),
       ('Data Analyst','A Data Analyst with skills in data visualization and statistical analysis needed. Responsibilities include analyzing data trends, creating reports, and supporting decision-making processes.',(SELECT id FROM Category WHERE name = 'IT' LIMIT 1),1300.0,2,6,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-09-01','2023-09-15'),
       ('Business Analyst','Experienced Business Analyst required to gather and analyze business requirements. Must be able to communicate effectively with stakeholders and provide actionable insights.',(SELECT id FROM Category WHERE name = 'IT' LIMIT 1),1400.0,3,7,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-09-10','2023-10-01'),
       ('SEO Specialist','SEO Specialist needed to improve website visibility and search rankings. Responsibilities include keyword research, on-page optimization, and monitoring SEO performance.',(SELECT id FROM Category WHERE name = 'Development' LIMIT 1),1200.0,2,5,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-10-01','2023-10-10'),
       ('Content Writer','Creative Content Writer required to produce engaging and high-quality content. Must have experience with content strategy, SEO writing, and producing content across various platforms.',(SELECT id FROM Category WHERE name = 'Design' LIMIT 1),1100.0,1,4,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-10-15','2023-11-01'),
       ('Systems Administrator','Systems Administrator with experience in managing IT infrastructure needed. Responsibilities include maintaining servers, troubleshooting issues, and ensuring system reliability.',(SELECT id FROM Category WHERE name = 'IT' LIMIT 1),1600.0,4,8,TRUE,(SELECT id FROM Users WHERE name = 'DetalingStudio' LIMIT 1),'2023-11-01','2023-11-15'),
